import Foundation
import Observation

/// One rolling commentary card written during a live PL match. Generated by
/// the gd-live-brief cloud routine, triggered at HT and 75' by match-watcher.
/// iOS polls live-brief-current every 60s during a live window and renders
/// the latest brief as a LiveMatchCard at the top of the feed (T2+ only).
struct LiveMatchBrief: Codable, Identifiable, Equatable {
    let id: UUID
    let teamId: String
    let matchId: String
    let headline: String
    let body: String
    /// Match minute when the trigger fired. May be nil for synthetic /
    /// test rows; live rows always have it.
    let minute: Int?
    /// Trigger label: "HT" / "75" for v1; future "goal" / "redcard" / etc.
    /// Used for display ("HT" → "HALF TIME") and analytics. May be nil for
    /// legacy rows but should always be populated by the routine going
    /// forward.
    let triggerLabel: String?
    let generatedAt: Date
    /// Group standings table for the live box (WC group). Nil when unavailable.
    let standings: LiveStandings?
    /// Who scored and when, chronological. Nil/empty when no goals yet.
    let scorers: [Scorer]?

    enum CodingKeys: String, CodingKey {
        case id, minute, standings, scorers
        case teamId = "team_id"
        case matchId = "match_id"
        case headline, body
        case triggerLabel = "trigger_label"
        case generatedAt = "generated_at"
    }

    /// One goal in the live box. `minute` is the pre-formatted match minute
    /// ("47'" / "45+2'"); `player` is the scorer name (or "Own goal"); `team`
    /// is the scoring side's short name. `penalty` tags a spot-kick.
    struct Scorer: Codable, Equatable, Identifiable {
        let side: String
        let team: String
        let player: String
        let minute: String
        let penalty: Bool?
        /// Optional headshot URL string (API-Football CDN), key "photo".
        /// Nil for legacy rows / players without a photo on file — synthesized
        /// Codable's decodeIfPresent-for-Optional keeps this backward and
        /// forward compatible with rows that predate this field.
        let photo: String?
        var id: String { "\(side)-\(player)-\(minute)" }

        /// Convenience URL for AsyncImage call sites.
        var photoURL: URL? {
            guard let photo else { return nil }
            return URL(string: photo)
        }
    }

    /// The group table rendered under the live score, sourced deterministically
    /// from the team page's standings card by live-brief-current.
    struct LiveStandings: Codable, Equatable {
        let competitionLabel: String
        let entries: [Row]

        enum CodingKeys: String, CodingKey {
            case competitionLabel = "competition_label"
            case entries
        }

        struct Row: Codable, Equatable, Identifiable {
            let rank: Int
            let team: String
            let played: Int
            let won: Int
            let drawn: Int
            let lost: Int
            let gd: Int
            let points: Int
            var id: Int { rank }
        }
    }

    /// Display-friendly label for the card header.
    var displayTriggerLabel: String {
        guard let label = triggerLabel else { return "LIVE" }
        switch label {
        case "HT":  return "HALF TIME"
        case "FT":  return "FULL TIME"
        case "75":  return "75 MIN"
        default:    return label.uppercased()
        }
    }
}

/// The live brief for the entity the feed is on, polled once for both the
/// Feed and Matchday (council MD-01-08). It lived inside FeedView, so the
/// score stopped the moment she switched tab. MainTabView runs `poll`; the
/// tabs only read.
@MainActor @Observable
final class LiveBriefPoller {
    static let shared = LiveBriefPoller()

    /// The latest brief, or nil when nothing is live (204).
    private(set) var brief: LiveMatchBrief?
    /// Whose brief it is: a reader on another entity shows nothing.
    private(set) var entityId: String?
    /// No successful poll for three minutes: the card's clock stops.
    private(set) var isPaused = false
    private var lastAt = Date()

    /// Polls live-brief-current until cancelled: every 60 s near a match,
    /// ten minutes otherwise.
    func poll(entityId: String?) async {
        if entityId != self.entityId { brief = nil; isPaused = false }
        self.entityId = entityId
        guard let teamId = entityId else { return }

        while !Task.isCancelled {
            do {
                brief = try await APIClient.shared.fetchCurrentLiveBrief(teamId: teamId)
                lastAt = Date()
                isPaused = false
            } catch {
                // A cancelled poll (tab view gone, entity switched) is not
                // silence from the server.
                if Task.isCancelled { return }
                // Network blip or backend hiccup. A transient error keeps the
                // last good card; three minutes without one stops its clock
                // and says so, ten minutes takes it down. During the 24 Oct
                // outage the card would have shown a frozen 1-0 with the
                // clock running past 100'.
                let silent = Date().timeIntervalSince(lastAt)
                if silent > 600 { brief = nil } else if silent > 180 { isPaused = true }
                #if DEBUG
                print("⚠️ live brief poll error: \(error)")
                #endif
            }
            // 60s between polls near a match, ten minutes otherwise: a T2+
            // feed on screen polled once a minute all week for a 204 (bug
            // hunt 2026-10-27). Near = from 15 min before the next kickoff on
            // the cached club page to four hours after; no page or no
            // fixture means near, so a match is never missed.
            let kickoff = TeamPageCache.load(teamId: teamId)?.content.cards.nextFixture
                .flatMap { MatchContext.parseISO($0.date) }
            let near = brief != nil || kickoff.map {
                let mins = $0.timeIntervalSinceNow / 60
                return mins < 15 && mins > -240
            } ?? true
            do {
                try await Task.sleep(for: .seconds(near ? 60 : 600))
            } catch {
                return
            }
        }
    }
}
